
use ovmf_prebuilt::{Arch, FileType, Prebuilt, Source};
use std::process::Command;

fn main() {
    // Get the bootable image generated by build.rs.
    let uefi_path = env!("UEFI_PATH");

    // Download/find prebuilt UEFI firmware.
    let prebuilt =
        Prebuilt::fetch(Source::LATEST, "target/ovmf")
            .expect("Failed to obtain OVMF firmware");

    let code = prebuilt.get_file(Arch::X64, FileType::Code);
    let vars = prebuilt.get_file(Arch::X64, FileType::Vars);

    // Configure QEMU.
    let mut qemu = Command::new("qemu-system-x86_64");

    qemu
        .arg("-enable-kvm")
        .arg("-serial")
        .arg("mon:stdio")
        .arg("-drive")
        .arg(format!("format=raw,file={uefi_path}"))
        .arg("-drive")
        .arg(format!(
            "if=pflash,format=raw,unit=0,file={},readonly=on",
            code.display()
        ))
        .arg("-drive")
        .arg(format!(
            "if=pflash,format=raw,unit=1,file={},snapshot=on",
            vars.display()
        ));

    // Start our virtual machine.
    let status = qemu.status().expect("Failed to start QEMU");

    if !status.success() {
        eprintln!("QEMU exited with an error: {status}");
    }
}
